input.command:
firecrawl interact --timeout 120 --code '
for (let i=0;i<8;i++){ 
  const b = page.getByRole("button",{name:/load more|show more/i});
  if (await b.count()) { await b.first().click(); } else { await page.mouse.wheel(0,20000); }
  await page.waitForTimeout(1500);
}
const links = await page.$$eval("a[href*=\"/detail/\"]", a=>[...new Set(a.map(x=>x.href))]);
console.log(links.length); console.log(links.join("\n"));
' -o .firecrawl/morelinks.txt; head -60 .firecrawl/morelinks.txt

